{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C07"],
      "claim": "The closest analogue (Morgan 0.2987), a fused morpholine-pyrimidine with an aminopyridine, gave minimal brain levels after oral dosing in rats, directly indicating poor CNS access for this scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "A closely related analogue bearing the same morpholine and aminopyrimidine motifs had total brain AUC0-8 of only 104 ng·h/g after 5 mg/kg oral dosing and was labeled poor penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "CLR457, a morpholine/aminopyrimidine-containing kinase inhibitor, had a brain/plasma AUC ratio of 0.07, showing minimal CNS penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "A morpholinopyrimidine-fluoroindazole radiotracer reached 2.8 SUV in rat brain within 5 min, demonstrating that this heteroaromatic morpholine-pyrimidine class can be brain penetrant.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C06"],
      "claim": "PF-06455943, a morpholine-containing pyrrolopyrimidine, showed favorable brain uptake and specific binding in rodent PET, supporting CNS access for similar morpholine heteroaromatics.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C09"],
      "claim": "SHP099, an aminopyrimidine with a basic amine, achieved brain-plasma ratios >1 in mice, showing aminopyrimidine-containing molecules can have meaningful CNS exposure.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Although several morpholine/aminopyrimidine analogues are brain-penetrant, the highest-similarity direct PK records (C07, C10) and the closely related CLR457 (C01) show minimal brain exposure; the query's fused thienopyran-morpholine-aminopyrimidine scaffold is therefore predicted to lack meaningful CNS access.",
  "evidence_gaps": [
    "No direct experimental measurement for the query molecule.",
    "Morgan similarities are modest (0.20-0.30), limiting transfer strength.",
    "Efflux transporter involvement and unbound brain concentrations are not reported for the closest analogues.",
    "Conflicting labels for low-SUV PET record C02 complicate interpretation."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

